// Official lists are links only: no personal data or inferred admission rates.
export function renderInsights(record, selectedTerm, lang, escape, safeURL) {
  if (!record) return '';
  const zh=lang==='zh', tr=(cn,my)=>zh?cn:my, e=escape;
  const link=(url,label)=>url?`<a href="${e(safeURL(url))}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a>`:'';
  const year=y=>y?`${e(y)} ${tr('資料','ကိုးကား')}`:tr('版本待確認','မူကွဲ အတည်ပြုရန်');
  const fee=record.applicationFee||{};
  const confirmed=fee.status==='confirmed'&&Number.isFinite(fee.amount);
  const status=confirmed&&fee.amountLabel?e(fee.amountLabel):confirmed?(fee.amount===0?tr('NT$0 · 官方明確免收','NT$0 · တရားဝင် အခမဲ့'): `${e(fee.currency||'TWD')} ${Number(fee.amount).toLocaleString('en-US')}`):tr('目前未找到可靠申請費資料','လျှောက်လွှာကြေးကို မအတည်ပြုနိုင်သေးပါ');
  const feeSeason=(fee.intakes||[]).map(t=>t==='fall'?tr('秋季','ဆောင်းဦး'):tr('春季','နွေဦး')).join(' / ');
  const feeNote=confirmed?tr('顯示最近已確認年度的費用；不代表2027各季已公告相同金額。','နောက်ဆုံးအတည်ပြုနိုင်သောနှစ်၏ ကြေးဖြစ်သည်။ 2027 အတွက် တူညီမည်ဟု မဆိုလိုပါ။'):tr('未知不等於免費。附件讀不到與簡章未寫金額，會分別保留原因。','မသိရခြင်းသည် အခမဲ့ဟု မဆိုလိုပါ။ ဖိုင်ဖတ်မရခြင်းနှင့် ပမာဏမဖော်ပြခြင်းကို သီးခြားမှတ်တမ်းတင်ထားသည်။');
  const notices=record.admissionNotices||[];
  const season=term=>{const rows=notices.filter(n=>n.semester===term);return rows.length?`<ul class="original-list">${rows.map(n=>`<li><strong>${e(n.academicYear)}-${term==='fall'?'1':'2'}</strong> · <span lang="zh-Hant">${e(n.sourceTitle)}</span><br>${link(n.sourceUrl,tr('查看官方原始榜單／公告','တရားဝင် မူရင်းစာရင်း / ကြေညာချက်ကြည့်ရန်'))}</li>`).join('')}</ul>`:`<p class="insight-empty">${tr('尚未找到官方榜單','တရားဝင် ဝင်ခွင့်စာရင်း မတွေ့သေးပါ')}</p>`;};
  const t=record.tuition?.[0], money=n=>`NT$${Number(n).toLocaleString('en-US')}`;
  return `<section class="school-insights"><div class="insight-intro"><h3>${tr('申請費與獎學金','လျှောက်လွှာကြေးနှင့် ပညာသင်ဆု')}</h3><p>${tr('各項分別標示來源年度；歷年資料仍可參考。','အချက်အလက်တစ်ခုစီတွင် ကိုးကားနှစ်ကို ဖော်ပြထားသည်။ ယခင်နှစ်အချက်အလက်ကိုလည်း ကိုးကားနိုင်သည်။')}</p></div>
  <div class="insight-section"><h4>${tr('一般外國學位生申請費','ပုံမှန် နိုင်ငံခြားသားဘွဲ့သင်တန်း လျှောက်လွှာကြေး')}</h4><p class="fee-result"><strong>${status}</strong></p><p class="source-year">${year(fee.academicYear)}${feeSeason?' · '+e(feeSeason):''}</p>${fee.intakes?.length&&!fee.intakes.includes(selectedTerm)?`<p class="insight-caution">${tr('此費用來源不涵蓋目前選取的入學季，僅作另一季參考。','ဤကြေးသည် ရွေးထားသောဝင်ခွင့်ရာသီအတွက် မဟုတ်ပါ။ အခြားရာသီကိုးကားသာ ဖြစ်သည်။')}</p>`:''}<p class="insight-caution">${feeNote}</p>${fee.notes?`<p class="detail-note" lang="zh-Hant">${e(fee.notes)}</p>`:''}${link(fee.sourceUrl,fee.sourceTitle||tr('官方來源','တရားဝင်ရင်းမြစ်'))}</div>
  ${record.scholarships?.length?`<div class="insight-section"><h4>${tr('外國學生獎助參考','နိုင်ငံခြားသား ပညာသင်ထောက်ပံ့ကြေး')}</h4>${record.scholarships.map(s=>`<article class="scholarship-card"><h5 lang="zh-Hant">${e(s.scope)}</h5>${!zh&&s.summaryMy?`<p lang="my">${e(s.summaryMy)}</p>`:''}<p lang="zh-Hant">${e(s.award||'金額與條件尚未能確認；請查看官方入口。')}</p><p class="source-year">${year(s.academicYear)}${s.policyDate?' · '+e(s.policyDate):''}</p>${s.continuation||s.application||s.restrictions?`<details class="scholarship-conditions"><summary>${tr('申請方式、續領與限制','လျှောက်ထားခြင်း၊ ဆက်လက်ရယူခြင်းနှင့် ကန့်သတ်ချက်များ')}</summary>${[['application','申請方式','လျှောက်ထားရန်'],['continuation','續領條件','ဆက်လက်ရယူရန်'],['restrictions','重要限制／版本差異','ကန့်သတ်ချက် / မူကွဲကွာခြားမှု']].filter(([key])=>s[key]).map(([key,cn,my])=>`<p><strong>${tr(cn,my)}</strong><br><span lang="zh-Hant">${e(s[key])}</span></p>`).join('')}</details>`:''}<p>${link(s.sourceUrl,tr('官方規定','တရားဝင်စည်းမျဉ်း'))}${s.relatedSourceUrl?' · '+link(s.relatedSourceUrl,tr('相關辦法／簡章','သက်ဆိုင်ရာ စည်းမျဉ်း / လမ်းညွှန်')):''}</p></article>`).join('')}<p class="insight-caution">${tr('獎助依申請資格、審核及名額辦理。除明文規定的直接減免外，不視為保證取得。','ပညာသင်ဆုများသည် အရည်အချင်း၊ စစ်ဆေးမှုနှင့် အရေအတွက်ကန့်သတ်ချက်အပေါ် မူတည်သည်။ တိုက်ရိုက်လျှော့ပေးကြောင်း ဖော်ပြထားခြင်းမှလွဲ၍ ရရှိမည်ဟု အာမခံမထားပါ။')}</p></div>`:''}
  ${t?`<div class="insight-section"><h4>${tr('學雜費參考','ကျောင်းလခ ကိုးကား')}</h4><p><strong>${money(t.amountMin)}–${money(t.amountMax)}</strong> · ${year(t.academicYear)} · ${tr('每學期，依院系而異','တစ်စာသင်ကာလ၊ ဘာသာရပ်အလိုက် ကွဲပြားသည်')}</p><p lang="zh-Hant">${e(t.scope||'')}</p>${link(t.sourceUrl,tr('官方來源','တရားဝင်ရင်းမြစ်'))}</div>`:''}
  ${record.requirements?.length?`<details class="insight-section"><summary>${tr('申請文件與語言參考','စာရွက်စာတမ်းနှင့် ဘာသာစကား')}</summary>${record.requirements.map(r=>`<p class="requirement">${year(r.academicYear)} · ${e(zh?r.text:r.summaryMy||r.text)} ${link(r.sourceUrl,tr('官方要求','တရားဝင်လိုအပ်ချက်'))}</p>`).join('')}</details>`:''}
  <details class="insight-section"><summary>${tr('歷年官方原始榜單','ယခင်နှစ် တရားဝင် မူရင်းဝင်ခွင့်စာရင်း')}</summary><p class="detail-note">${tr('只提供官方原始連結；不統計人數、不推算錄取率。','တရားဝင်မူရင်းလင့်ခ်များသာ ဖြစ်သည်။ လူဦးရေ သို့မဟုတ် လက်ခံနှုန်းကို မတွက်ချက်ပါ။')}</p>${['fall','spring'].map(term=>`<details class="season-insight" ${selectedTerm===term?'open':''}><summary>${term==='fall'?tr('秋季','ဆောင်းဦး'):tr('春季','နွေဦး')}</summary>${season(term)}</details>`).join('')}</details>
  ${record.audit?.gaps?.length?`<details class="insight-gaps"><summary>${tr('尚待確認的項目','အတည်ပြုရန် ကျန်ရှိသည့်အချက်များ')} · ${e(record.audit.checked)}</summary><ul lang="zh-Hant">${record.audit.gaps.map(g=>`<li>${e(g)}</li>`).join('')}</ul></details>`:''}</section>`;
}
